const assert = require('node:assert/strict');
const { chromium } = require('playwright-core');

(async () => {
  const [base, cookie] = process.argv.slice(2);
  const browser = await chromium.launch({ executablePath: process.env.BROWSER_EXECUTABLE || '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  try {
    const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
    await context.addCookies([{ name: 'session', value: cookie, url: base, httpOnly: true }]);
    const page = await context.newPage();
    await page.goto(base + '/customers/new');
    await page.locator('[name=display_name]').fill('Browser master journey');
    await page.locator('[name=account_type]').selectOption('company');
    assert.equal(await page.locator('[name=status]').count(), 0);
    await Promise.all([page.waitForURL(/\/customers\/\d+\/edit$/), page.getByRole('button', { name: 'Save and continue', exact: true }).click()]);
    const customer = page.url().replace(/\/edit$/, '');
    const contacts = customer + '/contacts';
    await page.goto(contacts + '/new');
    await page.getByLabel('First name', { exact: true }).fill('Duplicate person');
    await page.getByLabel('Email', { exact: true }).fill('browser-needle@test.example');
    await page.getByLabel('Service Notes', { exact: true }).fill('Retained service instructions');
    await page.locator('[name=is_primary]').check();
    await Promise.all([page.waitForURL(/\/contacts\/\d+$/), page.getByRole('button', { name: 'Save', exact: true }).click()]);
    const first = page.url();
    assert.match(await page.locator('body').innerText(), /Primary Contact/);
    await page.goto(contacts + '/new');
    await page.getByLabel('First name', { exact: true }).fill('Duplicate person');
    await page.getByLabel('Email', { exact: true }).fill('browser-needle@test.example');
    await Promise.all([page.waitForURL(/\/contacts\/\d+$/), page.getByRole('button', { name: 'Save', exact: true }).click()]);
    await page.goto(contacts + '?search=duplicate&per_page=50');
    assert.equal(await page.locator('[name=per_page]').inputValue(), '50');
    assert.equal(await page.getByRole('link', { name: 'Duplicate person', exact: true }).count(), 2);
    await page.goto(base + '/customers?search=browser-needle');
    assert.match(await page.locator('body').innerText(), /Contact match/);
    await page.goto(customer + '/locations/new');
    await page.getByLabel('Title', { exact: true }).fill('Browser premises');
    await page.getByLabel('Address line 1', { exact: true }).fill('31 Persisted Avenue');
    await page.locator('[name=is_primary]').check();
    await Promise.all([page.waitForURL(/\/locations\/\d+$/), page.getByRole('button', { name: 'Save', exact: true }).click()]);
    const location = page.url();
    assert.match(await page.locator('body').innerText(), /Primary Location/);
    await page.goto(base + '/customers?search=persisted%20avenue');
    assert.match(await page.locator('body').innerText(), /Location match/);
    await page.goto(first);
    await Promise.all([page.waitForNavigation(), page.getByRole('button', { name: 'Archive', exact: true }).click()]);
    assert.match(await page.locator('body').innerText(), /Archived/);
    assert.equal(await page.getByRole('link', { name: 'Edit Contact', exact: true }).count(), 0);
    await page.goto(customer + '/archive');
    await Promise.all([page.waitForNavigation(), page.getByRole('button', { name: 'Confirm archive', exact: true }).click()]);
    assert.match(await page.locator('body').innerText(), /Archived on/);
    await Promise.all([page.waitForNavigation(), page.getByRole('button', { name: 'Restore', exact: true }).click()]);
    await page.goto(contacts + '?archived=1');
    assert.equal(await page.getByRole('link', { name: 'Duplicate person', exact: true }).count(), 2);
    await page.goto(location);
    assert.match(await page.locator('body').innerText(), /Archived/);
    assert.doesNotMatch(await page.locator('body').innerText(), /Primary Location/);
    await page.goto(first);
    assert.match(await page.locator('body').innerText(), /Archived/);
    await Promise.all([page.waitForNavigation(), page.getByRole('button', { name: 'Restore', exact: true }).click()]);
    assert.doesNotMatch(await page.locator('body').innerText(), /Primary Contact/);
    assert.match(await page.locator('body').innerText(), /Retained service instructions/);
    await page.reload();
    assert.match(await page.locator('body').innerText(), /Retained service instructions/);
    console.log('Persisted mobile Chromium: explicit kind, duplicate Contacts, primary, search, query state, reviewed Customer cascade, independent child restore without primary revival.');
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
